ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c     This file contains the exponential representation routines for
c     Laplace equation in R^2
c
ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c
c --- tables for iprec = 0,1,2,3,4,5; (2,3,6,9,12,15 digits)
c
c
c lwtsexp2 - exponential representation for 1/z in R^2
c       1/s = \int_0^{+\infty} exp(-st) dt
c       s = u+i*v, u in [1,4], v in [0, 4]
c
c
c --- tables for 17 digits of accuracy
c
c
c lwtsexp2a - exponential representation for 1/z in R^2
c       1/s = \int_0^{+\infty} exp(-st) dt
c       s = u+i*v, u in [1,4], v in [0, 4]
c       tables for n=2..40, up to 17 digits
c              
c       
c --- tables for full double/extended precision accuracy
c
c
c lwtsexp2b - exponential representation for 1/z in R^2
c       1/s = \int_0^{+\infty} exp(-st) dt
c       s = u+i*v, u in [1,4], v in [0, 4]
c       tables for n=2..66, up to 28 digits
c
c
c --- tables for full double/extended precision accuracy (box separation by 2)
c
c
c lwtsexp2b_sep2 - exponential representation for 1/z in R^2
c       1/s = \int_0^{+\infty} exp(-st) dt
c       s = u+i*v, u in [2,6], v in [0, 6]
c       tables for n=2..55, up to 28 digits
c       
c
ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
c
c
        subroutine lwtsexp2(iprec,xs,ws,n)
        implicit real *8 (a-h,o-z)
        dimension xs(*),ws(*)
c       
c       This subroutine returns the nodes and weights for 
c       the exponential representation 
c
c       1/s = \int_0^{+\infty} exp(-st) dt
c
c       s = u+i*v, u in [1,4], v in [0, 4]
c
c       Input parameter:
c       
c       iprec - precision required:
c           iprec = 0 - 2 digits
c           iprec = 1 - 3 digits
c           iprec = 2 - 6 digits
c           iprec = 3 - 9 digits
c           iprec = 4 - 12 digits
c           iprec = 5 - 15 digits
c
c       Output parameters:
c
c       n - the number of nodes
c       xs - the nodes: real *8 (n)
c       ws - the weights: real *8 (n)
c
        n = 0
c
        if( iprec .eq. 0 ) then
        n = 7
        call lwtsexp2b(n,xs,ws,err)
        endif
c
        if( iprec .eq. 1 ) then
        n = 9
        call lwtsexp2b(n,xs,ws,err)
        endif
c
        if( iprec .eq. 2 ) then
        n = 16
        call lwtsexp2b(n,xs,ws,err)
        endif
c
        if( iprec .eq. 3 ) then
        n = 23
        call lwtsexp2b(n,xs,ws,err)
        endif
c
        if( iprec .eq. 4 ) then
        n = 30
        call lwtsexp2b(n,xs,ws,err)
        endif
c
        if( iprec .eq. 5 ) then
        n = 36
        call lwtsexp2b(n,xs,ws,err)
        endif
c
        return
        end
c
c
c
ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
