c
        subroutine lwtsexp2_sep2(iprec,xs,ws,n)
        implicit real *8 (a-h,o-z)
        dimension xs(*),ws(*)
c       
c       This subroutine returns the nodes and weights for 
c       the exponential representation 
c
c       1/s = \int_0^{+\infty} exp(-st) dt
c
c       s = u+i*v, u in [2,6], v in [2, 6]
c
c       Input parameter:
c       
c       iprec - precision required:
c           iprec = 0 - 2 digits
c           iprec = 1 - 3 digits
c           iprec = 2 - 6 digits
c           iprec = 3 - 9 digits
c           iprec = 4 - 12 digits
c           iprec = 5 - 15 digits
c
c       Output parameters:
c
c       n - the number of nodes
c       xs - the nodes: real *8 (n)
c       ws - the weights: real *8 (n)
c
        n = 0
c
        if( iprec .eq. 0 ) then
        n = 5
        call lwtsexp2b_sep2(n,xs,ws,err)
        endif
c
        if( iprec .eq. 1 ) then
        n = 7
        call lwtsexp2b_sep2(n,xs,ws,err)
        endif
c
        if( iprec .eq. 2 ) then
        n = 12
        call lwtsexp2b_sep2(n,xs,ws,err)
        endif
c
        if( iprec .eq. 3 ) then
        n = 18
        call lwtsexp2b_sep2(n,xs,ws,err)
        endif
c
        if( iprec .eq. 4 ) then
        n = 23
        call lwtsexp2b_sep2(n,xs,ws,err)
        endif
c
        if( iprec .eq. 5 ) then
        n = 29
        call lwtsexp2b_sep2(n,xs,ws,err)
        endif
c
        return
        end
